// @ts-check
import { readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import mermaid from 'astro-mermaid';

// Sidebar is generated by sync.mjs from the canonical docs tree (spine -> modules -> glossary -> ADRs).
const sidebar = JSON.parse(readFileSync(new URL('./src/sidebar.json', import.meta.url)));

// Click-to-zoom lightbox for content images (screenshots, diagrams). Self-contained (no plugin — the
// markdown-pipeline plugins conflict with astro-mermaid): a click on any `.sl-markdown-content img`
// opens it full-size in an overlay; click anywhere or press Escape to close.
const IMAGE_ZOOM_CSS = `
.sl-markdown-content img { cursor: zoom-in; }
.img-zoom-overlay { position: fixed; inset: 0; z-index: 9999; background: rgba(0,0,0,.85);
  display: flex; align-items: center; justify-content: center; padding: 2rem; cursor: zoom-out;
  opacity: 0; transition: opacity .15s ease; }
.img-zoom-overlay.open { opacity: 1; }
.img-zoom-overlay img { max-width: 100%; max-height: 100%; border-radius: 6px;
  box-shadow: 0 8px 40px rgba(0,0,0,.6); }
`;
const IMAGE_ZOOM_JS = `
(function () {
  function open(src, alt) {
    var ov = document.createElement('div');
    ov.className = 'img-zoom-overlay';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-label', alt || 'Enlarged image');
    var big = document.createElement('img');
    big.src = src; big.alt = alt || '';
    ov.appendChild(big);
    function close() { ov.remove(); document.removeEventListener('keydown', onKey); }
    function onKey(e) { if (e.key === 'Escape') close(); }
    ov.addEventListener('click', close);
    document.addEventListener('keydown', onKey);
    document.body.appendChild(ov);
    requestAnimationFrame(function () { ov.classList.add('open'); });
  }
  function init() {
    document.querySelectorAll('.sl-markdown-content img').forEach(function (img) {
      if (img.dataset.zoomBound) return;
      img.dataset.zoomBound = '1';
      img.addEventListener('click', function () { open(img.currentSrc || img.src, img.alt); });
    });
  }
  document.addEventListener('DOMContentLoaded', init);
  document.addEventListener('astro:page-load', init);
})();
`;

// https://astro.build/config
export default defineConfig({
  site: 'https://refplat.org',
  integrations: [
    // astro-mermaid must come BEFORE starlight so it processes ```mermaid fences first.
    mermaid({ theme: 'default', autoTheme: true }),
    starlight({
      title: 'refplat',
      tagline: 'A reference implementation of a multi-tenant internal developer platform.',
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/asanexample/platform' }],
      sidebar,
      customCss: ['./src/styles/learn.css'],
      // Click any content image (screenshots, diagrams) to zoom it to a full-size overlay.
      head: [
        { tag: 'style', content: IMAGE_ZOOM_CSS },
        { tag: 'script', content: IMAGE_ZOOM_JS },
      ],
      // Wrap long code lines instead of horizontal-scrolling (continuation lines stay indented).
      expressiveCode: { defaultProps: { wrap: true, preserveIndent: true } },
    }),
  ],
});
